-- PostgreSQL 17 / Neon. Ejecutar conectado directamente a la base tallermecanico.
-- Use el host directo de Neon (sin -pooler) para aplicar este esquema.
BEGIN;

CREATE TABLE IF NOT EXISTS public."Clientes" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY CONSTRAINT "PK_Clientes" PRIMARY KEY,
    "Nombre" character varying(100) NOT NULL,
    "Documento" character varying(20) NOT NULL,
    "Telefono" character varying(20),
    CONSTRAINT "CK_Clientes_Nombre" CHECK (length(btrim("Nombre")) > 0),
    CONSTRAINT "CK_Clientes_Documento" CHECK (length(btrim("Documento")) > 0)
);
CREATE UNIQUE INDEX IF NOT EXISTS "UX_Clientes_Documento" ON public."Clientes" ("Documento");

CREATE TABLE IF NOT EXISTS public."Vehiculos" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY CONSTRAINT "PK_Vehiculos" PRIMARY KEY,
    "Placa" character varying(15) NOT NULL,
    "Marca" character varying(50) NOT NULL,
    "Modelo" character varying(50) NOT NULL,
    "Anio" integer NOT NULL,
    "ClienteId" integer NOT NULL,
    CONSTRAINT "CK_Vehiculos_Placa" CHECK (length(btrim("Placa")) > 0),
    CONSTRAINT "CK_Vehiculos_Marca" CHECK (length(btrim("Marca")) > 0),
    CONSTRAINT "CK_Vehiculos_Modelo" CHECK (length(btrim("Modelo")) > 0),
    CONSTRAINT "CK_Vehiculos_Anio" CHECK ("Anio" BETWEEN 1900 AND 2100),
    CONSTRAINT "FK_Vehiculos_Clientes" FOREIGN KEY ("ClienteId")
        REFERENCES public."Clientes" ("Id") ON DELETE NO ACTION
);
CREATE UNIQUE INDEX IF NOT EXISTS "UX_Vehiculos_Placa" ON public."Vehiculos" ("Placa");
CREATE INDEX IF NOT EXISTS "IX_Vehiculos_ClienteId" ON public."Vehiculos" ("ClienteId");

CREATE TABLE IF NOT EXISTS public."Usuarios" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY CONSTRAINT "PK_Usuarios" PRIMARY KEY,
    "Correo" character varying(254) NOT NULL,
    "ClaveHash" character varying(100) NOT NULL,
    "Rol" character varying(30) NOT NULL
);
CREATE UNIQUE INDEX IF NOT EXISTS "UX_Usuarios_Correo" ON public."Usuarios" ("Correo");

INSERT INTO public."Clientes" ("Nombre", "Documento", "Telefono")
VALUES ('Cliente de ejemplo', 'LAB13-001', '999111222')
ON CONFLICT ("Documento") DO NOTHING;

INSERT INTO public."Vehiculos" ("Placa", "Marca", "Modelo", "Anio", "ClienteId")
SELECT 'LAB13-ABC', 'Toyota', 'Corolla', 2020, "Id"
FROM public."Clientes" WHERE "Documento" = 'LAB13-001'
ON CONFLICT ("Placa") DO NOTHING;

COMMIT;

